extern crate proc_macro;
use proc_macro::TokenStream;
#[proc_macro]
pub fn make(_: TokenStream) -> TokenStream {
    (1..=40).map(|i| format!("pub fn item_{}() {{}}\n", i)).collect::<String>().parse().unwrap()
}
#[proc_macro]
pub fn reexports(_: TokenStream) -> TokenStream {
    (1..=40).map(|i| format!("pub use inner::item_{};\n", i)).collect::<String>().parse().unwrap()
}

