trait Other {
    type Choose<L, R>;
}

// first impl
impl<T: Trait> Other for T {
    type Choose<L, R> = L;
}

// second impl: overlaps the first one once `S<W>: Trait` holds
impl<T> Other for S<T> {
    type Choose<L, R> = R;
}

#[cfg(rpass1)]
